window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8992cc14124aa5f9"]={"versions": [{"id": "FIG-8992cc14124aa5f9", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm mit Interaktionsreferenzen / Interaction Uses und kombinierten Fragmenten).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, BSW-Modul <code>Dcm</code> (Diagnostic Communication Manager, SWS-Kapitel 9 Execution Sequences).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des internen Kontroll- und Datenflusses zur Abwicklung eines einzelnen ereignisgesteuerten Antworttelegramms im Rahmen des UDS-Dienstes <em>ResponseOnEvent</em> (ROE, Service 0x86). Es visualisiert das Architekturmuster des internen „Request Loopback“ (Simulated Request), bei dem ein durch den Event-Manager im DSP erkannter Trigger eine interne Re-Injektion eines Diagnose-Requests (hier: <em>ReadDataByIdentifier</em>, Service 0x22) in die DCM-Sublayer auslöst.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Lifelines (Akteure / Submodule):</p>\n<ul class=\"fig-list\"><li><strong><code>«module» PduR</code>:</strong> AUTOSAR PDU Router (unterlagerte Kommunikationsschicht für I-PDU/TP-Routing).\n</li><li><strong><code>«module» Dsl</code>:</strong> DCM - Diagnostic Session Layer (Verwaltung von Diagnose-Sessions, Timings, PDU-Empfang/-Sendung und PduR-Interaktion).\n</li><li><strong><code>«module» Dsd</code>:</strong> DCM - Diagnostic Service Dispatcher (Prüfung von Service-IDs, Session-/Security-Rechten und Dispatching an den zuständigen Interpreter).\n</li><li><strong><code>«module» Dsp</code>:</strong> DCM - Diagnostic Service Processing (Ausführung der konkreten UDS-Service-Handler, hier ROE-Event-Manager und 0x22-Interpreter).\n</li><li><strong><code>Dcm User</code>:</strong> Applikation / Software Component (SW-C), CDD oder BSW-Modul, welches die Nutzdaten für das angeforderte DID bereitstellt.\n</li></ul>\n<p class=\"fig-p\">Beteiligte Schnittstellen und Signale:</p>\n<ul class=\"fig-list\"><li><strong>Interne DCM-APIs (Sublayer-Kopplung):</strong>\n<ul class=\"fig-list\"><li><code>DslInternal_ResponseOnOneEvent(const Dcm_MsgType, Dcm_MsgLenType, uint16)</code>: Request-Injektion von DSP an DSL.\n</li><li><code>Data_Indication_functionality()</code>: Interner Aufruf von DSL an DSD zur Signalisierung eines (simulierten) eingehenden Telegramms.\n</li><li><code>ReadDataByIdentifier service interpreter()</code>: DSD-Dispatching an den Service-Interpreter im DSP.\n</li><li><code>DspInternal_DcmReadDataByIdentifier()</code>: Rückgabe des Interpreters an DSD nach Datenaggregation.\n</li><li><code>Data_Confirmation_functionality()</code>: DSL-zu-DSD Bestätigungspfad.\n</li><li><code>DspInternal_DcmConfirmation(Dcm_IdContextType, PduIdType, Dcm_ConfirmationStatusType)</code>: Quittierung des Übertragungsstatus an DSP.\n</li></ul>\n</li><li><strong>AUTOSAR Standard- &amp; Port-Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><code>ReadData(Did specific type): Std_ReturnType</code>: Synchroner/asynchroner Port-Aufruf (z. B. Schnittstelle <code>DataServices_{Data}</code> bzw. <code>ReadData</code>) an den <code>Dcm User</code>.\n</li><li><code>Dcm_TpTxConfirmation(PduIdType, Std_ReturnType)</code>: Standardisiertes TP-Transmit-Callback vom <code>PduR</code> an den <code>Dsl</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Phase 1: Voraussetzung &amp; Event-Aktivierung (Kopfbereich &amp; Notes)</h5>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Der ROE-Dienst (0x86) wurde zuvor regulär empfangen (synchron/asynchron via <code>Receive a request message ...</code>) und konfiguriert/gestartet.\n</li><li><strong>Event Manager:</strong> Innerhalb des DSP läuft der Event-Manager, welcher auf das konfigurierte Ereignis (z. B. DTC-Statuswechsel, <code>onChangeOfDataIdentifier</code>) wartet.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Fragment <code>Simulate Request</code> (Interne Dienstanforderung)</h5>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Das Ereignis tritt ein. DSP initiiert über <code>DslInternal_ResponseOnOneEvent(...)</code> die Generierung des Antworttelegramms bei DSL.\n</li><li><strong>Dispatching:</strong>\n<ul class=\"fig-list\"><li>DSL spiegelt dies als regulären Eingang über <code>Data_Indication_functionality()</code> in den DSD ein.\n</li><li>DSD leitet die Anforderung an den zuständigen Service-Interpreter im DSP weiter (<code>ReadDataByIdentifier service interpreter()</code>).\n</li></ul>\n</li><li><strong>Datenauslese:</strong>\n<ul class=\"fig-list\"><li>DSP ruft <code>ReadData(...)</code> am <code>Dcm User</code> (SW-C) auf.\n</li><li>Der <code>Dcm User</code> liefert die geforderten DID-Daten synchron (oder gepuffert/asynchron) mit <code>Std_ReturnType</code> (z. B. <code>E_OK</code>) zurück.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 3: Fragment <code>Response</code> (Telegrammabschluss &amp; Tx-Bestätigung)</h5>\n<ol class=\"fig-list\"><li><strong>Kaskadierter Return:</strong>\n<ul class=\"fig-list\"><li>DSP schließt Service-Interpretation ab und signalisiert dies per <code>DspInternal_DcmReadDataByIdentifier()</code> an DSD.\n</li><li>DSD kehrt via <code>Data_Indication_functionality()</code> zu DSL zurück.\n</li><li>DSL quittiert den Abschluss der Event-Simulation via <code>DslInternal_ResponseOnOneEvent()</code> an den DSP Event-Manager.\n</li></ul>\n</li><li><strong>Übertragung &amp; Bestätigungskette (Tx Confirmation):</strong>\n<ul class=\"fig-list\"><li>Die PDU wird über den PduR auf den Bus übertragen (hier ausgeblendet).\n</li><li>Nach erfolgreichem/fehlerhaftem Abschluss des TP-Transfers meldet PduR das Ergebnis via <code>Dcm_TpTxConfirmation(PduId, Std_ReturnType)</code> an DSL.\n</li><li>DSL propagiert das Ergebnis über <code>Data_Confirmation_functionality()</code> an DSD.\n</li><li>DSD benachrichtigt DSP über <code>DspInternal_DcmConfirmation(IdContext, PduId, Status)</code>.\n</li><li>Die Bestätigungen kehren kaskadierend zurück bis zur Quittierung an den PduR (<code>Dcm_TpTxConfirmation()</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architekturmuster „Request Simulation“:</strong> Der DCM führt für ROE-Events keinen separaten, proprietären Sendepfad ein. Stattdessen wird die reguläre DSD/DSP-Pipeline wiederverwendet. Dadurch greifen dieselben Validierungs- und Pufferungsmechanismen wie bei einem externen Diagnose-Request.\n</li><li><strong>Pufferverwaltung &amp; Reentrancy:</strong>\n<ul class=\"fig-list\"><li>Der DSL-Puffer für die ROE-Übertragung muss getrennt von Standard-Tester-Requests verwaltet werden (<code>DcmDslProtocolRx/TxBuffer</code>), um Pufferkollisionen mit parallel laufender Standarddiagnose zu verhindern.\n</li><li>SW-Cs müssen darauf vorbereitet sein, dass <code>ReadData()</code> unabhängig von einem externen Diagnose-Request zyklisch oder ereignisgesteuert durch den DCM-Task aufgerufen wird.\n</li></ul>\n</li><li><strong>Transaktionssicherheit &amp; Bestätigung:</strong>\n<ul class=\"fig-list\"><li>Der Event-Manager im DSP darf das Ereignis erst dann als vollständig abgearbeitet werten (z. B. für Zählerdekremetierung oder One-Shot-Clear), wenn die Bestätigungskette über <code>DspInternal_DcmConfirmation()</code> mit Status <code>DCM_RES_POS_CONF</code> erfolgreich durchlaufen wurde. Bei Übertragungsfehlern (<code>E_NOT_OK</code>) greift das modulspezifische Retry- bzw. Fehlerbehandlungsverhalten.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-590710a8138bf45d", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm mit Interaktionsreferenzen / Interaction Uses und kombinierten Fragmenten).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, BSW-Modul <code>Dcm</code> (Diagnostic Communication Manager, SWS-Kapitel 9 Execution Sequences).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des internen Kontroll- und Datenflusses zur Abwicklung eines einzelnen ereignisgesteuerten Antworttelegramms im Rahmen des UDS-Dienstes <em>ResponseOnEvent</em> (ROE, Service 0x86). Es visualisiert das Architekturmuster des internen „Request Loopback“ (Simulated Request), bei dem ein durch den Event-Manager im DSP erkannter Trigger eine interne Re-Injektion eines Diagnose-Requests (hier: <em>ReadDataByIdentifier</em>, Service 0x22) in die DCM-Sublayer auslöst.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Lifelines (Akteure / Submodule):</p>\n<ul class=\"fig-list\"><li><strong><code>«module» PduR</code>:</strong> AUTOSAR PDU Router (unterlagerte Kommunikationsschicht für I-PDU/TP-Routing).\n</li><li><strong><code>«module» Dsl</code>:</strong> DCM - Diagnostic Session Layer (Verwaltung von Diagnose-Sessions, Timings, PDU-Empfang/-Sendung und PduR-Interaktion).\n</li><li><strong><code>«module» Dsd</code>:</strong> DCM - Diagnostic Service Dispatcher (Prüfung von Service-IDs, Session-/Security-Rechten und Dispatching an den zuständigen Interpreter).\n</li><li><strong><code>«module» Dsp</code>:</strong> DCM - Diagnostic Service Processing (Ausführung der konkreten UDS-Service-Handler, hier ROE-Event-Manager und 0x22-Interpreter).\n</li><li><strong><code>Dcm User</code>:</strong> Applikation / Software Component (SW-C), CDD oder BSW-Modul, welches die Nutzdaten für das angeforderte DID bereitstellt.\n</li></ul>\n<p class=\"fig-p\">Beteiligte Schnittstellen und Signale:</p>\n<ul class=\"fig-list\"><li><strong>Interne DCM-APIs (Sublayer-Kopplung):</strong>\n<ul class=\"fig-list\"><li><code>TriggerTransmissionOfServiceToRespondToRecord()</code>: Request-Injektion von DSP an DSL.\n</li><li><code>Data_Indication_functionality()</code>: Interner Aufruf von DSL an DSD zur Signalisierung eines (simulierten) eingehenden Telegramms.\n</li><li><code>ReadDataByIdentifier service interpreter()</code>: DSD-Dispatching an den Service-Interpreter im DSP.\n</li><li><code>DspInternal_DcmReadDataByIdentifier()</code>: Rückgabe des Interpreters an DSD nach Datenaggregation.\n</li><li><code>Data_Confirmation_functionality()</code>: DSL-zu-DSD Bestätigungspfad.\n</li><li><code>DspInternal_DcmConfirmation(Dcm_IdContextType, PduIdType, Dcm_ConfirmationStatusType)</code>: Quittierung des Übertragungsstatus an DSP.\n</li></ul>\n</li><li><strong>AUTOSAR Standard- &amp; Port-Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><code>ReadData(Did specific type): Std_ReturnType</code>: Synchroner/asynchroner Port-Aufruf (z. B. Schnittstelle <code>DataServices_{Data}</code> bzw. <code>ReadData</code>) an den <code>Dcm User</code>.\n</li><li><code>Dcm_TpTxConfirmation(PduIdType, Std_ReturnType)</code>: Standardisiertes TP-Transmit-Callback vom <code>PduR</code> an den <code>Dsl</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Phase 1: Voraussetzung &amp; Event-Aktivierung (Kopfbereich &amp; Notes)</h5>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Der ROE-Dienst (0x86) wurde zuvor regulär empfangen (synchron/asynchron via <code>Receive a request message ...</code>) und konfiguriert/gestartet.\n</li><li><strong>Event Manager:</strong> Innerhalb des DSP läuft der Event-Manager, welcher auf das konfigurierte Ereignis (z. B. DTC-Statuswechsel, <code>onChangeOfDataIdentifier</code>) wartet.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Fragment <code>Simulate Request</code> (Interne Dienstanforderung)</h5>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Das Ereignis tritt ein. DSP initiiert über <code>TriggerTransmissionOfServiceToRespondToRecord()</code> die Generierung des Antworttelegramms bei DSL.\n</li><li><strong>Dispatching:</strong>\n<ul class=\"fig-list\"><li>DSL spiegelt dies als regulären Eingang über <code>Data_Indication_functionality()</code> in den DSD ein.\n</li><li>DSD leitet die Anforderung an den zuständigen Service-Interpreter im DSP weiter (<code>ReadDataByIdentifier service interpreter()</code>).\n</li></ul>\n</li><li><strong>Datenauslese:</strong>\n<ul class=\"fig-list\"><li>DSP ruft <code>ReadData(...)</code> am <code>Dcm User</code> (SW-C) auf.\n</li><li>Der <code>Dcm User</code> liefert die geforderten DID-Daten synchron (oder gepuffert/asynchron) mit <code>Std_ReturnType</code> (z. B. <code>E_OK</code>) zurück.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 3: Fragment <code>Response</code> (Telegrammabschluss &amp; Tx-Bestätigung)</h5>\n<ol class=\"fig-list\"><li><strong>Kaskadierter Return:</strong>\n<ul class=\"fig-list\"><li>DSP schließt Service-Interpretation ab und signalisiert dies per <code>DspInternal_DcmReadDataByIdentifier()</code> an DSD.\n</li><li>DSD kehrt via <code>Data_Indication_functionality()</code> zu DSL zurück.\n</li><li>DSL quittiert den Abschluss der Event-Simulation via <code>TriggerTransmissionOfServiceToRespondToRecord()</code> an den DSP Event-Manager.\n</li></ul>\n</li><li><strong>Übertragung &amp; Bestätigungskette (Tx Confirmation):</strong>\n<ul class=\"fig-list\"><li>Die PDU wird über den PduR auf den Bus übertragen (hier ausgeblendet).\n</li><li>Nach erfolgreichem/fehlerhaftem Abschluss des TP-Transfers meldet PduR das Ergebnis via <code>Dcm_TpTxConfirmation(PduId, Std_ReturnType)</code> an DSL.\n</li><li>DSL propagiert das Ergebnis über <code>Data_Confirmation_functionality()</code> an DSD.\n</li><li>DSD benachrichtigt DSP über <code>DspInternal_DcmConfirmation(IdContext, PduId, Status)</code>.\n</li><li>Die Bestätigungen kehren kaskadierend zurück bis zur Quittierung an den PduR (<code>Dcm_TpTxConfirmation()</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architekturmuster „Request Simulation“:</strong> Der DCM führt für ROE-Events keinen separaten, proprietären Sendepfad ein. Stattdessen wird die reguläre DSD/DSP-Pipeline wiederverwendet. Dadurch greifen dieselben Validierungs- und Pufferungsmechanismen wie bei einem externen Diagnose-Request.\n</li><li><strong>Pufferverwaltung &amp; Reentrancy:</strong>\n<ul class=\"fig-list\"><li>Der DSL-Puffer für die ROE-Übertragung muss getrennt von Standard-Tester-Requests verwaltet werden (<code>DcmDslProtocolRx/TxBuffer</code>), um Pufferkollisionen mit parallel laufender Standarddiagnose zu verhindern.\n</li><li>SW-Cs müssen darauf vorbereitet sein, dass <code>ReadData()</code> unabhängig von einem externen Diagnose-Request zyklisch oder ereignisgesteuert durch den DCM-Task aufgerufen wird.\n</li></ul>\n</li><li><strong>Transaktionssicherheit &amp; Bestätigung:</strong>\n<ul class=\"fig-list\"><li>Der Event-Manager im DSP darf das Ereignis erst dann als vollständig abgearbeitet werten (z. B. für Zählerdekremetierung oder One-Shot-Clear), wenn die Bestätigungskette über <code>DspInternal_DcmConfirmation()</code> mit Status <code>DCM_RES_POS_CONF</code> erfolgreich durchlaufen wurde. Bei Übertragungsfehlern (<code>E_NOT_OK</code>) greift das modulspezifische Retry- bzw. Fehlerbehandlungsverhalten.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8992cc14124aa5f9", "to": "FIG-590710a8138bf45d", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DslInternal_ResponseOnOneEvent(const Dcm_MsgType, Dcm_MsgLenType, uint16)</code>: Ersetzt durch <code>TriggerTransmissionOfServiceToRespondToRecord()</code> beim Aufruf von <code>Dsp</code> an <code>Dsl</code> im Fragment <code>Simulate Request</code>.\n</li><li><code>DslInternal_ResponseOnOneEvent()</code>: Ersetzt durch <code>TriggerTransmissionOfServiceToRespondToRecord()</code> beim Rücksprung von <code>Dsl</code> an <code>Dsp</code> im Fragment <code>Response</code>.\n</li></ul>"}]};
